// Photo asset "share-card" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/share-card.js"></script>
//   <img data-asset="share-card" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "share-card": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="share-card"]').forEach(function (img) { img.src = window.ASSETS["share-card"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
